<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Raport English RPG</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/core@1.4.0/dist/css/tabler.min.css"><style>body{background:#eef1f7}.wrap{max-width:950px;margin:auto;padding:30px 16px}.hero{background:#24345f;color:#fff;padding:25px;border-radius:18px}.box{background:#fff;border-radius:14px;padding:18px;margin-top:15px}.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}.kpi{background:#f4f1ff;padding:15px;border-radius:12px}.kpi b{font-size:26px}</style></head><body><main class="wrap"><a href="<?= base_url('belajar/english-quest'); ?>">← Peta Dunia</a><section class="hero mt-3"><h1>Raport English RPG</h1><h2><?= html_escape($report['profile']['hero_name']); ?></h2><p>Class <?= html_escape(str_replace('_',' ',$report['profile']['class_code'])); ?> · Streak <?= (int)$report['profile']['streak_days']; ?> hari · Reputation <?= (int)$report['profile']['reputation']; ?></p></section><section class="box kpis"><div class="kpi"><b><?= count(array_filter($report['episodes'],fn($e)=>!empty($e['is_completed']))); ?></b><div>Chapter selesai</div></div><div class="kpi"><b><?= (int)($report['mastery']['total']??0); ?></b><div>Kosakata ditemui</div></div><div class="kpi"><b><?= round((float)($report['mastery']['average']??0)); ?>%</b><div>Rata-rata mastery</div></div><div class="kpi"><b><?= (int)$report['profile']['total_correct']; ?></b><div>Jawaban benar</div></div></section><section class="box"><h2>Kemampuan</h2><?php foreach($report['types'] as $t): ?><div class="d-flex justify-content-between border-bottom py-2"><span><?= html_escape(ucfirst($t['challenge_type'])); ?></span><b><?= (int)$t['correct']; ?>/<?= (int)$t['attempts']; ?> · <?= $t['attempts']?round($t['correct']/$t['attempts']*100):0; ?>%</b></div><?php endforeach; ?></section><section class="box"><h2>Kosakata perlu perhatian</h2><?php foreach($report['weak_words'] as $w): ?><span class="badge bg-orange-lt m-1"><?= html_escape($w['word']); ?> <?= (int)$w['mastery_score']; ?>%</span><?php endforeach; ?></section></main></body></html>
